import { describe, it } from "node:test";
import assert from "node:assert/strict";
import * as path from "path";
import { repoRoot } from "./helpers";
import { loadScan } from "../src/scan";

// The demo fixtures are generated by scripts/gen-examples.py (seeded RNG).
// These tests pin their shape so the README/demo can quote real numbers.
const EXAMPLES = path.join(repoRoot(), "examples");

describe("example fixtures", () => {
  it("session-before.jsonl parses as claude-code with a dominant tool", () => {
    const out = loadScan(path.join(EXAMPLES, "session-before.jsonl"));
    assert.equal(out.format, "claude-code");
    assert.ok(out.summary.totalCalls > 100, `calls: ${out.summary.totalCalls}`);
    const top = out.summary.tools[0];
    assert.equal(top.tool, "mcp__doc_lookup");
    const share = top.usd / out.summary.totalUsd;
    assert.ok(share > 0.4, `doc_lookup share: ${(share * 100).toFixed(1)}%`);
  });

  it("session-after.jsonl is the cut session (fewer calls, less spend)", () => {
    const before = loadScan(path.join(EXAMPLES, "session-before.jsonl")).summary;
    const after = loadScan(path.join(EXAMPLES, "session-after.jsonl")).summary;
    assert.ok(after.totalCalls < before.totalCalls);
    assert.ok(after.totalUsd < before.totalUsd);
    assert.ok(!after.tools.some((t) => t.tool === "mcp__doc_lookup"));
  });

  it("mcp-sample.jsonl parses as mcp-jsonl", () => {
    const out = loadScan(path.join(EXAMPLES, "mcp-sample.jsonl"));
    assert.equal(out.format, "mcp-jsonl");
    assert.equal(out.summary.totalCalls, 8);
  });
});
